class Patient {
    id: string;
    age: int;
    gender: string;
}

let p := new Patient {
    id     := "PAT001",
    age    := 55,
    gender := "M",
};
println(p.id);
println(p.age);

class Greeter {
    prefix: string;

    func say(self, name: string) {
        println(self.prefix + ", " + name + "!");
    }
}

let g := new Greeter {
    prefix := "Hello",
};
g.say("world");

class Rectangle {
    width: real;
    height: real;

    func area(self) -> real {
        return self.width * self.height;
    }
}

let rect := new Rectangle {
    width  := 5.0,
    height := 3.0,
};
let a := rect.area();
println(a);

let names := ["Alice", "Bob", "Carol"];
for (let i := 0; i < 3; i := i + 1) {
    println(names[i]);
}
